package rotasegura.dao;
import java.sql.*;
import java.util.*;
public class Repositorio implements AutoCloseable {
 private final Connection c;
 public Repositorio(String url) throws Exception {
 Class.forName("org.hsqldb.jdbcDriver"); c=DriverManager.getConnection(url,"SA","");
 if(!c.getMetaData().getTables(null,null,"CLIENTES",new String[]{"TABLE"}).next()) {
 exec("CREATE TABLE clientes(cpf VARCHAR(20) PRIMARY KEY,nome VARCHAR(120) NOT NULL,telefone VARCHAR(30) NOT NULL)");
 exec("CREATE TABLE veiculos(placa VARCHAR(12) PRIMARY KEY,marca VARCHAR(80),modelo VARCHAR(80),ano INTEGER,categoria VARCHAR(15),disponivel BOOLEAN NOT NULL)");
 exec("CREATE TABLE locacoes(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,cpf VARCHAR(20) NOT NULL,placa VARCHAR(12) NOT NULL,dias INTEGER NOT NULL,total DECIMAL(12,2),status VARCHAR(15),abertura TIMESTAMP,fechamento TIMESTAMP,CHECK(dias>0),FOREIGN KEY(cpf) REFERENCES clientes(cpf),FOREIGN KEY(placa) REFERENCES veiculos(placa))");
 exec("INSERT INTO veiculos VALUES(?,?,?,?,?,?)","ABC-1234","Fiat","Mobi",2024,"Popular",true);
 exec("INSERT INTO veiculos VALUES(?,?,?,?,?,?)","DEF-1234","Toyota","Corolla",2025,"Sedan",true);
 exec("INSERT INTO veiculos VALUES(?,?,?,?,?,?)","GHI-1234","Jeep","Compass",2025,"SUV",true);
 }
 }
 private PreparedStatement stmt(String sql,Object... args)throws SQLException {PreparedStatement p=c.prepareStatement(sql); for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);return p;}
 private int exec(String sql,Object... args)throws SQLException {try(PreparedStatement p=stmt(sql,args)){return p.executeUpdate();}}
 private List<Object[]> query(String sql,Object... args)throws SQLException {try(PreparedStatement p=stmt(sql,args);ResultSet r=p.executeQuery()){List<Object[]> l=new ArrayList<>();int n=r.getMetaData().getColumnCount();while(r.next()){Object[] a=new Object[n];for(int i=0;i<n;i++)a[i]=r.getObject(i+1);l.add(a);}return l;}}
 public List<Object[]> clientes()throws SQLException{return query("SELECT cpf,nome,telefone FROM clientes ORDER BY nome");}
 public List<Object[]> veiculos()throws SQLException{return query("SELECT placa,marca,modelo,ano,categoria,disponivel FROM veiculos ORDER BY placa");}
 public List<Object[]> locacoes()throws SQLException{return query("SELECT id,cpf,placa,dias,total,status,abertura,fechamento FROM locacoes ORDER BY id");}
 public Object[] veiculo(String placa)throws SQLException{return unico(query("SELECT placa,marca,modelo,ano,categoria,disponivel FROM veiculos WHERE placa=?",placa));}
 public Object[] locacao(int id)throws SQLException{return unico(query("SELECT id,cpf,placa,dias,total,status,abertura,fechamento FROM locacoes WHERE id=?",id));}
 private Object[] unico(List<Object[]> l){if(l.isEmpty())throw new IllegalArgumentException("Registro não encontrado.");return l.get(0);}
 public void cliente(boolean editar,String cpf,String nome,String tel)throws SQLException {if(editar)exec("UPDATE clientes SET nome=?,telefone=? WHERE cpf=?",nome,tel,cpf);else exec("INSERT INTO clientes VALUES(?,?,?)",cpf,nome,tel);}
 public void veiculo(boolean editar,String placa,String marca,String modelo,int ano,String cat)throws SQLException {if(editar){if(exec("UPDATE veiculos SET marca=?,modelo=?,ano=?,categoria=? WHERE placa=? AND disponivel=TRUE",marca,modelo,ano,cat,placa)!=1)throw new IllegalArgumentException("Veículo locado não pode ser editado.");}else exec("INSERT INTO veiculos VALUES(?,?,?,?,?,TRUE)",placa,marca,modelo,ano,cat);}
 public void excluirCliente(String cpf)throws SQLException{exec("DELETE FROM clientes WHERE cpf=?",cpf);}
 public void excluirVeiculo(String placa)throws SQLException{if(exec("DELETE FROM veiculos WHERE placa=? AND disponivel=TRUE",placa)!=1)throw new IllegalArgumentException("Veículo indisponível para exclusão.");}
 private interface Acao{void run()throws SQLException;}
 private void transacao(Acao a)throws SQLException{c.setAutoCommit(false);try{a.run();c.commit();}catch(SQLException|RuntimeException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}
 public void abrir(String cpf,String placa,int dias,double total)throws SQLException{transacao(()->{if(exec("UPDATE veiculos SET disponivel=FALSE WHERE placa=? AND disponivel=TRUE",placa)!=1)throw new IllegalArgumentException("Veículo indisponível.");exec("INSERT INTO locacoes(cpf,placa,dias,total,status,abertura) VALUES(?,?,?,?, 'ABERTA',CURRENT_TIMESTAMP)",cpf,placa,dias,total);});}
 public void editar(int id,int dias,double total)throws SQLException{if(exec("UPDATE locacoes SET dias=?,total=? WHERE id=? AND status='ABERTA'",dias,total,id)!=1)throw new IllegalArgumentException("Contrato não está aberto.");}
 public void fechar(int id,int dias,double total)throws SQLException{transacao(()->{Object[] l=locacao(id);if(exec("UPDATE locacoes SET dias=?,total=?,status='FECHADA',fechamento=CURRENT_TIMESTAMP WHERE id=? AND status='ABERTA'",dias,total,id)!=1)throw new IllegalArgumentException("Contrato já encerrado.");if(exec("UPDATE veiculos SET disponivel=TRUE WHERE placa=? AND disponivel=FALSE",l[2])!=1)throw new IllegalStateException("Status inconsistente.");});}
 public void cancelar(int id)throws SQLException{transacao(()->{Object[] l=locacao(id);if(exec("DELETE FROM locacoes WHERE id=? AND status='ABERTA'",id)!=1)throw new IllegalArgumentException("Histórico encerrado não pode ser removido.");exec("UPDATE veiculos SET disponivel=TRUE WHERE placa=?",l[2]);});}
 public void close()throws SQLException{exec("SHUTDOWN");c.close();}
}
